context.value:
{
  Type    : "Low_Stock"
  Title   : "Low Stock Alert"
  Message : ($low_stock_components_count|to_text) ~ " Components are below reorder point"
  Severity: "Warning"
}

{
  Type    : "Missing_BOM"
  Title   : "Missing BOM Alert"
  Message : ($products_missing_bom_count|to_text) ~ " Products on active orders are missing a BOM"
  Severity: "Warning"
}

{
  Type    : "Negative_Stock"
  Title   : "Negative Stock Alert"
  Message : ($negative_stock_components_count|to_text) ~ " Components are below 0 on hand"
  Severity: "Error"
}

{
  line_item_title   : $line_item.title
  shopify_variant_id: $line_item.variant_id
  reason            : "No active BOM found"
}

{
  line_item_title: $line_item.title
  component_id   : $bom_component.component_id
  reason         : "No allocation location determined"
}

{
  success: true
  message: "Order processed successfully"
  data   : {
    order_id: $order_record.id
    status: $final_internal_status
    allocation_stats: {
       processed: ($allocation_outcomes|count)
       missing_boms: ($missing_boms|count)
       missing_balances: ($missing_inventory_balances|count)
    }
    warnings: {
       boms: $missing_boms
       inventory: $missing_inventory_balances
    }
  }
}

{
  success: true
  message: "Order fulfilled successfully"
  data: {
    order: $final_order
    allocations: $processed_allocations
  }
}

{
  line_item_title: $line_item.title
  shopify_variant_id: $line_item.variant_id
  reason: "No active BOM found"
}

{
  line_item_title: $line_item.title
  component_id: $bom_component.component_id
  reason: "No allocation location determined"
}

{
  success: true
  message: "Order processed successfully"
  data: {
    order_id: $order_record.id
    status: $final_internal_status
    allocation_stats: {
      processed: ($allocation_outcomes|count)
      missing_boms: ($missing_boms|count)
      missing_balances: ($missing_inventory_balances|count)
    }
    warnings: {
      boms: $missing_boms
      inventory: $missing_inventory_balances
    }
  }
}

{
  labels  : $labels
  datasets: [
    {
      label: "Placed Orders",
      backgroundColor: "rgb(54, 162, 235)",
      data: $data_placed
    },
    {
      label: "Fulfilled Orders",
      backgroundColor: "rgb(75, 192, 192)",
      data: $data_fulfilled
    },
    {
      label: "Cancelled Orders",
      backgroundColor: "rgb(255, 99, 132)",
      data: $data_cancelled
    }
  ]
}
